/**
 * UUIDv7 primary keys (DATABASE §1: "generated by the app so ids sort by time").
 *
 * Layout: 48-bit Unix ms | version 7 | 12 random bits | variant 10 | 62 random bits.
 * Time-ordered ids keep b-tree inserts sequential, which matters for the invoice and
 * attendance tables the worker and reports scan.
 */
import { randomBytes } from "node:crypto";

export function uuidv7(now: number = Date.now()): string {
  const bytes = Buffer.alloc(16);
  // 6 bytes of big-endian milliseconds (writeUIntBE handles 48 bits).
  bytes.writeUIntBE(now, 0, 6);
  randomBytes(10).copy(bytes, 6);
  // Version 7 in the high nibble of byte 6, keeping its low 12 random bits.
  bytes[6] = (bytes[6]! & 0x0f) | 0x70;
  // RFC 4122 variant in byte 8, keeping the remaining 62 random bits.
  bytes[8] = (bytes[8]! & 0x3f) | 0x80;

  const hex = bytes.toString("hex");
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    hex.slice(12, 16),
    hex.slice(16, 20),
    hex.slice(20, 32),
  ].join("-");
}
